void Renderer::createDevice(){float pr=1;std::array<uint32_t,2> ids{graphicsFamily_,presentFamily_};std::vector<VkDeviceQueueCreateInfo>qs;for(int i=0;i<2;i++){if(i&&ids[i]==ids[0])continue;VkDeviceQueueCreateInfo q{VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO};q.queueFamilyIndex=ids[i];q.queueCount=1;q.pQueuePriorities=&pr;qs.push_back(q);}const char*ex[]={VK_KHR_SWAPCHAIN_EXTENSION_NAME};VkDeviceCreateInfo ci{VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO};ci.queueCreateInfoCount=(uint32_t)qs.size();ci.pQueueCreateInfos=qs.data();ci.enabledExtensionCount=1;ci.ppEnabledExtensionNames=ex;check(vkCreateDevice(physicalDevice_,&ci,nullptr,&device_),"vkCreateDevice");vkGetDeviceQueue(device_,graphicsFamily_,0,&graphicsQueue_);vkGetDeviceQueue(device_,presentFamily_,0,&presentQueue_);}
