void Renderer::createDepthResources(){VkImageCreateInfo ci{VK_STRUCTURE_TYPE_IMAGE_CREATE_INFO};ci.imageType=VK_IMAGE_TYPE_2D;ci.extent={extent_.width,extent_.height,1};ci.mipLevels=1;ci.arrayLayers=1;ci.format=VK_FORMAT_D32_SFLOAT;ci.tiling=VK_IMAGE_TILING_OPTIMAL;ci.initialLayout=VK_IMAGE_LAYOUT_UNDEFINED;ci.usage=VK_IMAGE_USAGE_DEPTH_STENCIL_ATTACHMENT_BIT;ci.samples=VK_SAMPLE_COUNT_1_BIT;ci.sharingMode=VK_SHARING_MODE_EXCLUSIVE;check(vkCreateImage(device_,&ci,nullptr,&depthImage_),"depth image");VkMemoryRequirements req{};vkGetImageMemoryRequirements(device_,depthImage_,&req);VkMemoryAllocateInfo ai{VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO};ai.allocationSize=req.size;ai.memoryTypeIndex=findMemoryType(req.memoryTypeBits,VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);check(vkAllocateMemory(device_,&ai,nullptr,&depthMemory_),"depth memory");check(vkBindImageMemory(device_,depthImage_,depthMemory_,0),"bind depth");VkImageViewCreateInfo vi{VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO};vi.image=depthImage_;vi.viewType=VK_IMAGE_VIEW_TYPE_2D;vi.format=VK_FORMAT_D32_SFLOAT;vi.subresourceRange={VK_IMAGE_ASPECT_DEPTH_BIT,0,1,0,1};check(vkCreateImageView(device_,&vi,nullptr,&depthView_),"depth view");}
