void Renderer::beginFrame(){check(vkWaitForFences(device_,1,&inFlight_[frame_],VK_TRUE,UINT64_MAX),"wait fence");VkResult r=vkAcquireNextImageKHR(device_,swapchain_,UINT64_MAX,imageAvailable_[frame_],VK_NULL_HANDLE,&imageIndex_);if(r==VK_ERROR_OUT_OF_DATE_KHR){recreateSwapchain();return;}if(r!=VK_SUCCESS&&r!=VK_SUBOPTIMAL_KHR)check(r,"acquire");check(vkResetFences(device_,1,&inFlight_[frame_]),"reset fence");check(vkResetCommandBuffer(commands_[frame_],0),"reset command");VkCommandBufferBeginInfo bi{VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};check(vkBeginCommandBuffer(commands_[frame_],&bi),"begin command");VkClearValue cv[2]{};cv[0].color={{.025f,.018f,.04f,1}};cv[1].depthStencil={1,0};VkRenderPassBeginInfo rp{VK_STRUCTURE_TYPE_RENDER_PASS_BEGIN_INFO};rp.renderPass=renderPass_;rp.framebuffer=framebuffers_[imageIndex_];rp.renderArea={{0,0},extent_};rp.clearValueCount=2;rp.pClearValues=cv;vkCmdBeginRenderPass(commands_[frame_],&rp,VK_SUBPASS_CONTENTS_INLINE);vkCmdBindPipeline(commands_[frame_],VK_PIPELINE_BIND_POINT_GRAPHICS,pipeline_);frameStarted_=true;}
